#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    /// <summary>
    /// 橄榄球僵尸的近战行为：只负责“采集/校验啃食目标”（碰撞到阻挡者时登记目标），
    /// 但不做原版的每帧持续啃咬伤害——橄榄球的伤害由两段挥砍
    /// （FootballZombie_States 的 AttackState）负责，否则两种伤害会叠加。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.footballZombie_Melee)]
    public class FootballZombie_MeleeBehaviour : EnemyMeleeBehaviour
    {
        public FootballZombie_MeleeBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        protected override void UpdateAI(Entity entity)
        {
            // 照抄基类 UpdateAI 的目标采集/校验部分，
            // 但故意跳过最后的每帧 MeleeAttack 持续伤害结算。
            if (!MeleeEnabled(entity))
                return;
            var targetID = GetMeleeTarget(entity);
            if (targetID != null && !ValidateMeleeTarget(entity, targetID.GetEntity(entity.Level)))
            {
                SetMeleeTarget(entity, null);
            }
            // 不做原版啃咬伤害：伤害由两段挥砍负责。
        }
    }
}
